const item = $input.first().json;
const msg = item.message;
const cb = item.callback_query;

const sender = msg ? msg.from : (cb ? cb.from : null);
const senderId = sender ? sender.id : null;
const senderUsername = sender && sender.username ? sender.username.toLowerCase() : '';

// Whitelist estricta de identidades autorizadas
const allowedIds = [1307787776, 8266932918];
const allowedUsernames = ['admin', 'admin_n8n_bot'];

const isAuthorized = (senderId && allowedIds.includes(senderId)) || 
                     (senderUsername && allowedUsernames.includes(senderUsername));

const chatId = msg ? msg.chat.id : (cb && cb.message ? cb.message.chat.id : senderId);
const callbackId = cb ? cb.id : null;

if (!isAuthorized) {
  return [{
    json: {
      authorized: false,
      senderId,
      senderUsername,
      chatId,
      action: 'UNAUTHORIZED'
    }
  }];
}

let rawText = (msg && (msg.text || msg.caption) ? (msg.text || msg.caption) : (cb && cb.data ? cb.data : '')).trim();

let targetUrl = '';
if (rawText.startsWith('/pentest ') || rawText.startsWith('/pentestweb ')) {
  const parts = rawText.split(' ');
  if (parts.length > 1) {
    targetUrl = parts[1].trim();
  }
} else if (rawText.startsWith('act_kali_select:')) {
  targetUrl = rawText.replace('act_kali_select:', '').trim();
}

const isUrl = /https?:\/\/[^\s]+/i.test(rawText);

let action = 'MENU';
if (targetUrl) {
  action = 'ACT_KALI_PENTEST_SELECT';
} else if (rawText === '/start' || rawText === '/menu' || rawText === 'menu') {
  action = 'MENU';
} else if (rawText === '/kali' || rawText === 'sub_kali') {
  action = 'SUB_KALI';
} else if (rawText.startsWith('act_kali')) {
  action = 'ACT_KALI';
} else if (rawText === 'hitl_kali_reboot') {
  action = 'CONFIRM_ACTION';
} else if (rawText === '/openwrt' || rawText === 'sub_openwrt') {
  action = 'SUB_OPENWRT';
} else if (rawText === '/synology' || rawText === 'sub_synology') {
  action = 'SUB_SYNOLOGY';
} else if (rawText === '/unifi' || rawText === 'sub_unifi') {
  action = 'SUB_UNIFI';
} else if (rawText === '/audit' || rawText === 'sub_audit') {
  action = 'SUB_AUDIT';
} else if (rawText.startsWith('act_owrt_')) {
  action = 'ACT_OPENWRT';
} else if (rawText.startsWith('act_syno_')) {
  action = 'ACT_SYNOLOGY';
} else if (rawText.startsWith('act_unifi_')) {
  action = 'ACT_UNIFI';
} else if (rawText.startsWith('act_audit_')) {
  action = 'ACT_AUDIT';
} else if (rawText.startsWith('cmd_confirm_')) {
  action = 'CONFIRM_ACTION';
} else if (isUrl) {
  action = 'CLIPPER';
} else {
  action = 'UNKNOWN_TEXT';
}

return [{
  json: {
    authorized: true,
    senderId,
    senderUsername,
    chatId,
    callbackId,
    rawText,
    targetUrl,
    action
  }
}];

const input = $input.first().json;
const now = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const report = `⚠️ *Compuerta de Aprobación HITL Superada*

• *Acción:* Ejecución confirmada por administrador.
• *Usuario:* \`${input.senderUsername || input.senderId}\`
• *Timestamp:* \`${now}\``;
return [{ json: { ...input, telegramMessage: report } }];

