const tgItem = $('Telegram Trigger').first()?.json?.message || {};
const msgText = tgItem.text || tgItem.caption || '';
const rawMatch = msgText.match(/https?:\/\/[^\s]+/);
const rawUrl = rawMatch ? rawMatch[0] : '';
let urlClean = rawUrl.replace(/[.,;:!?)">']+$/, '');
const comentario = msgText.replace(rawUrl, '').trim();

// Desacortador de URL principal
async function unshorten(url) {
  if (!url || typeof url !== 'string') return url;
  if (url.includes('linkedin.com/redir/redirect')) {
    const m = url.match(/[?&]url=([^&]+)/);
    if (m) {
      try { return decodeURIComponent(m[1]); } catch(e) {}
    }
  }
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 4000);
    const resp = await fetch(url, {
      method: 'GET',
      redirect: 'follow',
      signal: controller.signal,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' }
    });
    clearTimeout(timeout);
    return resp.url || url;
  } catch(e) {
    return url;
  }
}

if (urlClean) {
  urlClean = await unshorten(urlClean);
}

let isGitHub = false;
let ghRepo = '';
const ghMatch = urlClean.match(/https?:\/\/github\.com\/([^\/\s]+)\/([^\/\s?#]+)/i);
if (ghMatch) {
  isGitHub = true;
  ghRepo = `${ghMatch[1]}/${ghMatch[2]}`;
}

const hostMatch = urlClean.match(/https?:\/\/(?:www\.)?([^\/\s:]+)/i);
const dominio = hostMatch ? hostMatch[1].toLowerCase() : 'web';

return [{
  json: {
    urlOriginal: urlClean,
    comentario,
    isGitHub,
    ghRepo,
    dominio
  }
}];

const prep = $('Preparar Enlace').first()?.json || {};
const urlOriginal = prep.urlOriginal || '';
const comentario = prep.comentario || '';
let contenidoTexto = '';
let tituloDetectado = '';

const inputJson = $input.first()?.json || {};

// 1. Si vino de GitHub API (tiene full_name)
if (inputJson.full_name) {
  tituloDetectado = inputJson.full_name;
  contenidoTexto = `Repositorio: ${inputJson.full_name}\nDescripción: ${inputJson.description || 'Sin descripción'}\nLenguaje: ${inputJson.language || 'N/A'}\nTopics: ${(inputJson.topics || []).join(', ')}`;
}

// 2. Si vino de Jina Reader o HTML Fallback (tiene data)
const rawData = typeof inputJson.data === 'string' ? inputJson.data : JSON.stringify(inputJson.data || '');
if (!contenidoTexto && rawData) {
  const mTitle = rawData.match(/^Title:\s*(.+)$/m);
  if (mTitle) {
    tituloDetectado = mTitle[1].trim();
    contenidoTexto = rawData.substring(0, 6000);
  } else {
    const tm = rawData.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (tm) tituloDetectado = tm[1].replace(/\s+/g, ' ').trim();
    const dm = rawData.match(/<meta[^>]*name=["']description["'][^>]*content=["'](.*?)["']/i) || rawData.match(/<meta[^>]*property=["']og:description["'][^>]*content=["'](.*?)["']/i);
    if (dm) contenidoTexto = `Descripción Web: ${dm[1].trim()}`;
    if (!contenidoTexto) {
      contenidoTexto = rawData.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 3000);
    }
  }
}

if (!contenidoTexto) {
  contenidoTexto = `URL: ${urlOriginal}. Comentario: ${comentario || 'Enlace guardado desde Telegram.'}`;
}

// Helper para desacortar y seguir redirects usando this.helpers.httpRequest
const unshorten = async (url) => {
  if (!url || typeof url !== 'string') return url;

  // Si es un redirector de LinkedIn
  if (url.includes('linkedin.com/redir/redirect')) {
    const m = url.match(/[?&]url=([^&]+)/);
    if (m) {
      try {
        const decoded = decodeURIComponent(m[1]);
        if (decoded.includes('lnkd.in')) {
          url = decoded;
        } else {
          return decoded;
        }
      } catch(e) {}
    }
  }

  // Si es un acortador lnkd.in (interstitial HTML)
  if (url.includes('lnkd.in/')) {
    try {
      const html = await this.helpers.httpRequest({
        url: url,
        method: 'GET',
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        },
        timeout: 5000
      });
      if (typeof html === 'string') {
        const urls = html.match(/https?:\/\/[^"'\s<>]+/g) || [];
        for (const u of urls) {
          if (!u.includes('linkedin.com') && !u.includes('licdn.com')) {
            return u;
          }
        }
      }
    } catch(e) {}
  }

  // Para otros acortadores (bit.ly, t.co, tinyurl, etc.)
  try {
    const resp = await this.helpers.httpRequest({
      url: url,
      method: 'GET',
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
      },
      returnFullResponse: true,
      timeout: 5000
    });
    const final = resp.headers?.location || resp.responseUrl || resp.url || url;
    return final;
  } catch(e) {
    return url;
  }
};

// Extracción sobre TODO el documento rawData (no sólo contenidoTexto)
const urlRegex = /https?:\/\/[^\s)\]"'>]+/g;
const matches = (rawData.match(urlRegex) || []);
const ignoreList = [
  'licdn.com', 'schema.org', 'w3.org', 't.me/', 'wa.me/', 'doubleclick.net',
  'google.com/analytics', 'gravatar.com'
];

const candidateUrls = [];
for (let u of matches) {
  u = u.replace(/[.,;:!?)"'>]+$/, '');
  if (u === urlOriginal || u.startsWith(urlOriginal)) continue;
  if (/\.(png|jpg|jpeg|gif|svg|ico|webp|css|js|woff)$/i.test(u)) continue;

  // Normalizar de antemano si es redirector de LinkedIn para deduplicar
  if (u.includes('linkedin.com/redir/redirect')) {
    const m = u.match(/[?&]url=([^&]+)/);
    if (m) {
      try {
        u = decodeURIComponent(m[1]);
      } catch(e) {}
    }
  }

  const low = u.toLowerCase();
  // Filtrar navegación interna de LinkedIn
  if ((low.includes('linkedin.com') && !low.includes('linkedin.com/redir/redirect')) || low.includes('licdn.com')) {
    continue;
  }
  if (ignoreList.some(ign => low.includes(ign))) continue;
  if (!candidateUrls.includes(u)) candidateUrls.push(u);
}

// Tomar hasta 15 candidatos para no penalizar timeouts
const targetCandidates = candidateUrls.slice(0, 15);

// Desacortar concurrentemente en paralelo
const unshortenedList = await Promise.all(targetCandidates.map(async (rawSub) => {
  const finalUrl = await unshorten(rawSub);
  return { rawSub, finalUrl };
}));

// Deduplicar URLs finales
const visitedFinalUrls = new Set();
visitedFinalUrls.add(urlOriginal.replace(/[?#].*$/, '').toLowerCase());

const uniqueSubList = [];
for (const item of unshortenedList) {
  const cleanFinal = item.finalUrl.replace(/[?#].*$/, '').toLowerCase();
  if (visitedFinalUrls.has(cleanFinal)) continue;
  visitedFinalUrls.add(cleanFinal);
  uniqueSubList.push(item);
}

// Consultar metadatos en paralelo
const subRecursosAnalizados = await Promise.all(uniqueSubList.map(async ({ rawSub, finalUrl }) => {
  let summary = '';
  const ghMatch = finalUrl.match(/github\.com\/([^\/\s]+)\/([^\/\s?#]+)/i);
  if (ghMatch) {
    try {
      const ghJson = await this.helpers.httpRequest({
        url: `https://api.github.com/repos/${ghMatch[1]}/${ghMatch[2]}`,
        method: 'GET',
        headers: {
          'User-Agent': 'n8n-bot',
          'Accept': 'application/vnd.github.v3+json'
        },
        json: true,
        timeout: 4500
      });
      if (ghJson && ghJson.full_name) {
        summary = `GitHub: ${ghJson.full_name} - ${ghJson.description || 'Repositorio open source'} (Lenguaje: ${ghJson.language || 'N/A'})`;
      }
    } catch(e) {}
  }
  if (!summary) {
    try {
      const html = await this.helpers.httpRequest({
        url: finalUrl,
        method: 'GET',
        headers: { 'User-Agent': 'Mozilla/5.0' },
        timeout: 3500
      });
      if (typeof html === 'string') {
        const tm = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
        const dm = html.match(/<meta[^>]*name=["']description["'][^>]*content=["'](.*?)["']/i) || html.match(/<meta[^>]*property=["']og:description["'][^>]*content=["'](.*?)["']/i);
        if (tm || dm) {
          summary = `${tm ? tm[1].trim() : ''}${dm ? ' - ' + dm[1].trim() : ''}`.substring(0, 200);
        }
      }
    } catch(e) {}
  }

  return {
    urlOriginal: rawSub,
    urlFinal: finalUrl,
    descripcion: summary || 'Recurso de referencia'
  };
}));

let subTextoInfo = '';
if (subRecursosAnalizados.length > 0) {
  subTextoInfo = `\n\nSUB-ENLACES DETECTADOS Y ANALIZADOS:\n` + subRecursosAnalizados.map((s, i) => `${i+1}. [${s.urlFinal}]: ${s.descripcion}`).join('\n');
}

const promptText = `Analiza esta información de un recurso web y sus sub-enlaces citados. Genera UNICAMENTE un objeto JSON con este formato exacto:
{
  "titulo": "título conciso máximo 60 caracteres",
  "resumen": "resumen claro de 2 o 3 oraciones en español explicando qué es y su utilidad",
  "tags": ["tag1", "tag2", "tag3"],
  "subLinks": [
    {
      "url": "url_final",
      "titulo": "nombre o titulo del subrecurso",
      "descripcion": "explicación en 1 frase de qué aporta este link"
    }
  ]
}

REGLAS:
- No uses formato markdown para el JSON (solo el objeto crudo).
- Los tags deben ser en minúsculas y sin el símbolo #.
- Si hay sub-enlaces citados, llena el array subLinks con sus URLs finales analizadas. Si no hay sub-enlaces útiles, deja subLinks como [].
- Responde siempre en español.

DATOS:
URL Principal: ${urlOriginal}
Título preliminar: ${tituloDetectado}
Contenido extraído: ${contenidoTexto}${subTextoInfo}`;

return [{
  json: {
    urlOriginal,
    comentario,
    tituloDetectado,
    subRecursosAnalizados,
    promptText
  }
}];

