parameters.jsCode:
const prep = $('Preparar Prompt IA').first()?.json || {};
const urlOriginal = prep.urlOriginal || '';
const comentario = prep.comentario || '';
const tituloDetectado = prep.tituloDetectado || '';
const subRecursosAnalizados = prep.subRecursosAnalizados || [];

let dominio = 'web';
const hostMatch = urlOriginal.match(/https?:\/\/(?:www\.)?([^\/\s:]+)/i);
if (hostMatch) {
  dominio = hostMatch[1].toLowerCase();
}

const aiResp = $('AI Procesar Contenido')?.first()?.json;
let aiRaw = aiResp?.choices?.[0]?.message?.content || '';

let titulo = '';
let resumen = '';
let tags = [];
let aiSubLinks = [];

try {
  const jsonMatch = aiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    titulo = parsed.titulo || '';
    resumen = parsed.resumen || '';
    tags = Array.isArray(parsed.tags) ? parsed.tags : [];
    aiSubLinks = Array.isArray(parsed.subLinks) ? parsed.subLinks : [];
  }
} catch(e) {}

if (!titulo || titulo.length < 3) {
  if (tituloDetectado) {
    titulo = tituloDetectado;
  } else {
    const pathParts = urlOriginal.replace(/https?:\/\/[^\/]+/, '').split('/').filter(Boolean);
    const lastSlug = pathParts.pop() || '';
    if (lastSlug) {
      titulo = decodeURIComponent(lastSlug).replace(/[-_]+/g, ' ').replace(/\.(html?|php|aspx?)$/i, '').trim();
    }
    if (!titulo || titulo.length < 3) {
      titulo = dominio.charAt(0).toUpperCase() + dominio.slice(1);
    }
  }
}

if (!resumen) {
  resumen = 'Recurso web capturado automáticamente vía bot de Telegram.';
}

let categoriaFile = '14 - Misceláneos y Otros.md';
let tagCat = 'miscelaneos';
let tipoContenido = 'Recurso Web';
const uLower = urlOriginal.toLowerCase();

if (uLower.includes('github.com') || uLower.includes('gitlab.com')) {
  categoriaFile = '02 - GitHub y Proyectos Open Source.md';
  tagCat = 'github, open-source';
  tipoContenido = 'Repositorio Open Source';
} else if (uLower.includes('linkedin.com') || uLower.includes('lnkd.in')) {
  categoriaFile = '12 - LinkedIn y Red Profesional.md';
  tagCat = 'linkedin, profesional';
  tipoContenido = 'Perfil / Publicación Profesional';
} else if (uLower.includes('youtube.com') || uLower.includes('youtu.be') || uLower.includes('spotify.com')) {
  categoriaFile = '07 - Videos y Multimedia (YouTube).md';
  tagCat = 'video, multimedia';
  tipoContenido = 'Video / Multimedia';
} else if (/(security|seguridad|ciber|exploit|nmap|hack|cve|vulnerab|kali|wireshark|redeszone|fortinet|owasp|velocidex|velociraptor)/i.test(uLower)) {
  categoriaFile = '01 - Ciberseguridad, Redes y Hacking.md';
  tagCat = 'ciberseguridad, hacking';
  tipoContenido = 'Herramienta / Artículo de Ciberseguridad';
} else if (/(chatgpt|openai|claude|gemini|prompt|midjourney|leonardo\.ai|stable-diffusion|llm|ollama|huggingface|anthropic)/i.test(uLower)) {
  categoriaFile = '03 - Inteligencia Artificial y LLMs.md';
  tagCat = 'ia, llm, machine-learning';
  tipoContenido = 'Recurso de Inteligencia Artificial';
} else if (/(python|bash|javascript|golang|api|docker|devops|sql)/i.test(uLower)) {
  categoriaFile = '04 - Desarrollo, Python y DevOps.md';
  tagCat = 'desarrollo, python, devops';
  tipoContenido = 'Programación y DevOps';
} else if (/(linux|ubuntu|debian|sysadmin|proxmox|btrfs|zfs|openwrt)/i.test(uLower)) {
  categoriaFile = '05 - Sistemas Operativos y Sysadmin (Linux, Windows).md';
  tagCat = 'sysadmin, linux';
  tipoContenido = 'Administración de Sistemas';
} else if (/(curso|udemy|coursera|facialix|cursin|educalix|platzi)/i.test(uLower)) {
  categoriaFile = '06 - Cursos, Certificaciones y Libros.md';
  tagCat = 'curso, capacitacion';
  tipoContenido = 'Curso o Material de Estudio';
} else if (/(arcade|emuline|teknoparrot|retroarch|mame|roms|taito)/i.test(uLower)) {
  categoriaFile = '08 - Arcade, Emulación y Gaming.md';
  tagCat = 'arcade, emulacion';
  tipoContenido = 'Arcade y Gaming';
} else if (/(aliexpress|mercadolibre|amazon)/i.test(uLower)) {
  categoriaFile = '11 - Compras y Hardware.md';
  tagCat = 'compras, hardware';
  tipoContenido = 'Hardware o Componente';
} else if (/(mega\.nz|mediafire|drive\.google)/i.test(uLower)) {
  categoriaFile = '13 - Descargas y Almacenamiento.md';
  tagCat = 'descargas, almacenamiento';
  tipoContenido = 'Descarga de Archivos';
} else if (/(xataka|genbeta|muycomputer|elchapuzasinformatico|softzone)/i.test(uLower)) {
  categoriaFile = '10 - Noticias Tech y Artículos.md';
  tagCat = 'noticias, tech';
  tipoContenido = 'Noticia Tecnológica';
}

if (!tags || tags.length === 0) {
  tags = tagCat.split(',').map(t => t.trim());
}

// Consolidar sub-enlaces finales asegurando que NINGUNO quede afuera
let subLinksFinales = [];
if (subRecursosAnalizados.length > 0) {
  subLinksFinales = subRecursosAnalizados.map(s => {
    const cleanUrl = s.urlFinal.replace(/[?#].*$/, '').toLowerCase();
    const matchAi = aiSubLinks.find(a => (a.url || '').replace(/[?#].*$/, '').toLowerCase() === cleanUrl);

    let tituloDisplay = matchAi?.titulo;
    if (!tituloDisplay) {
      const gh = s.urlFinal.match(/github\.com\/([^\/\s]+)\/([^\/\s?#]+)/i);
      if (gh) {
        tituloDisplay = `${gh[1]}/${gh[2]}`;
      } else {
        tituloDisplay = s.urlFinal.replace(/https?:\/\/(?:www\.)?/, '').split('/')[0];
      }
    }

    return {
      url: s.urlFinal,
      titulo: tituloDisplay,
      descripcion: matchAi?.descripcion || s.descripcion || 'Recurso de referencia'
    };
  });
} else if (aiSubLinks.length > 0) {
  subLinksFinales = aiSubLinks;
}

const now = new Date();
const dateStr = `${String(now.getDate()).padStart(2,'0')}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getFullYear()).slice(-2)}`;

let card = `\n### [${titulo.replace(/\[/g, '(').replace(/\]/g, ')')}](${urlOriginal})\n`;
card += `- **🌐 Dominio**: \`${dominio}\` | **📅 Fecha Compartido**: \`${dateStr}\`\n`;
card += `- **📂 Tipo de Contenido**: ${tipoContenido}\n`;
card += `- **📝 Descripción**: ${resumen}\n`;

if (subLinksFinales.length > 0) {
  card += `- **🔗 Recursos y Enlaces Analizados (${subLinksFinales.length})**:\n`;
  for (const s of subLinksFinales) {
    const sName = (s.titulo || s.url).replace(/\[/g, '(').replace(/\]/g, ')');
    card += `  - 🔹 [${sName}](${s.url}): ${s.descripcion || 'Recurso de referencia'}\n`;
  }
}

if (comentario) {
  card += `- **💬 Contexto Telegram**: *"${comentario.replace(/"/g, '\\"')}"*\n`;
}
card += `- **🏷️ Etiquetas**: #${tags.join(' #')} #captura-telegram\n\n***\n`;

// Formato HTML 100% seguro para Telegram
const escapeHtml = (str) => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let tgHtml = `✅ <b>Nota guardada en Obsidian</b>\n\n`;
tgHtml += `📄 <b>${escapeHtml(titulo)}</b>\n\n`;
tgHtml += `🏷️ ${escapeHtml(tags.map(t => '#' + t.replace(/\s+/g, '_')).join(' '))}\n`;
tgHtml += `🌐 <code>${escapeHtml(dominio)}</code>\n`;
tgHtml += `🔗 <a href="${escapeHtml(urlOriginal)}">Ver Enlace Original</a>\n\n`;
tgHtml += `📝 <b>Resumen:</b>\n${escapeHtml(resumen)}\n`;

if (subLinksFinales.length > 0) {
  tgHtml += `\n🔗 <b>Recursos citados (${subLinksFinales.length}):</b>\n`;
  for (const s of subLinksFinales) {
    const sTitle = escapeHtml(s.titulo || s.url);
    const sDesc = escapeHtml(s.descripcion || '');
    tgHtml += `• <a href="${escapeHtml(s.url)}"><b>${sTitle}</b></a>${sDesc ? ': ' + sDesc : ''}\n`;
  }
}

return [{
  json: {
    titulo,
    urlOriginal,
    dominio,
    categoriaFile,
    categoriaNombre: categoriaFile.replace('.md', ''),
    tipoContenido,
    resumen,
    tags,
    subLinksFinales,
    tgHtml,
    markdownCard: card,
    nombreArchivo: `${now.toISOString().split('T')[0]} - ${titulo.replace(/[\/\\:*?"<>|]/g, '').trim().substring(0, 60)}`
  }
}];

