           `Total de hosts activos: *6 dispositivos*\n` +
           `• *Timestamp:* \`${now}\``;

} else if (sub === 'act_kali_net') {
  report = `🌐 *Kali Linux — Topología de Red y Conectividad Dual*\n\n` +
           `🛡️ *Interfaz eth1 (Red macvlan_lan):*\n` +
