parameters.jsCode:
const input = $input.first().json;
const now = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const sub = input.rawText;

let report = '';

if (sub === 'act_kali_web_prompt') {
  report = "🌐 *Auditoría Web OWASP — Kali Linux*\n\n" +
           "Para iniciar la evaluación pericial, envía el comando con la URL del objetivo:\n" +
           "`/pentest <URL>`\n\n" +
           "_Ejemplo:_ `/pentest http://192.168.1.100:3000/#/`\n" +
           "_Ejemplo:_ `/pentest https://ejemplo.com`";

} else if (sub.startsWith('act_kali_run:')) {
  const parts = sub.split(':');
  const profile = parts[1];
  const targetUrl = parts.slice(2).join(':');

  const profNames = {
    'fast': '🟢 Rápido / Pasivo',
    'standard': '🟡 Estándar OWASP',
    'full': '🔴 Avanzado / Activo'
  };
  const profText = profNames[profile] || profile;

  // Extraer host y puerto limpio para el nombre de los entregables
  let cleanTarget = targetUrl.replace(/^https?:\/\//i, '').replace(/[\/?#].*$/, '');
  cleanTarget = cleanTarget.replace(/[^a-zA-Z0-9_.-]/g, '_');
  const d = new Date();
  const dateStr = d.getFullYear() + ('0' + (d.getMonth() + 1)).slice(-2) + ('0' + d.getDate()).slice(-2);

  const mdFile = `informe_pentest_${cleanTarget}_${dateStr}.md`;
  const qaFile = `reporte_qa_${cleanTarget}_${dateStr}.txt`;

  // Realizar auditoría HTTP real
  const startTime = Date.now();
  let httpCode = 0;
  let headers = {};
  let connError = null;
  let isHttps = targetUrl.toLowerCase().startsWith('https://');

  try {
    const res = await this.helpers.httpRequest({
      url: targetUrl,
      method: 'GET',
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 6000
    });
    httpCode = res.statusCode || 200;
    headers = res.headers || {};
  } catch (err) {
    connError = err.message || 'Conexión rechazada / Tiempo de espera agotado';
  }

  // Comprobar métodos OPTIONS si el host respondió
  let methodsAllowed = [];
  if (!connError && (profile === 'standard' || profile === 'full')) {
    try {
      const resOpt = await this.helpers.httpRequest({
        url: targetUrl,
        method: 'OPTIONS',
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 4000
      });
      const allowHdr = (resOpt.headers && (resOpt.headers['allow'] || resOpt.headers['public'])) || '';
      if (allowHdr) {
        methodsAllowed = allowHdr.split(',').map(m => m.trim().toUpperCase());
      }
    } catch (e) {
      // OPTIONS no soportado o bloqueado
    }
  }

  const elapsedSec = ((Date.now() - startTime) / 1000).toFixed(1);

  // Evaluar hallazgos reales
  const findings = [];

  if (!isHttps) {
    findings.push({
      title: 'Uso de Protocolo Inseguro en Texto Plano (HTTP)',
      severity: 'High',
      cwe: 'CWE-319'
    });
  }

  if (connError) {
    findings.push({
      title: `Servicio Inaccesible o Conexión Rechazada (${cleanTarget})`,
      severity: 'High',
      cwe: 'CWE-404'
    });
  } else {
    // Evaluar cabeceras de seguridad reales
    const hdrKeys = Object.keys(headers).map(k => k.toLowerCase());
    if (isHttps && !hdrKeys.includes('strict-transport-security')) {
      findings.push({
        title: 'Ausencia de Cabecera Strict-Transport-Security (HSTS)',
        severity: 'Medium',
        cwe: 'CWE-319'
      });
    }
    if (!hdrKeys.includes('content-security-policy')) {
      findings.push({
        title: 'Ausencia de Cabecera Content-Security-Policy (CSP)',
        severity: 'Medium',
        cwe: 'CWE-693'
      });
    }
    if (!hdrKeys.includes('x-frame-options') && !hdrKeys.includes('content-security-policy')) {
      findings.push({
        title: 'Protección Insuficiente Contra Clickjacking (Falta X-Frame-Options)',
        severity: 'Medium',
        cwe: 'CWE-1021'
      });
    }
    if (!hdrKeys.includes('x-content-type-options')) {
      findings.push({
        title: 'Ausencia de Cabecera X-Content-Type-Options',
        severity: 'Low',
        cwe: 'CWE-693'
      });
    }
    if (hdrKeys.includes('server') || hdrKeys.includes('x-powered-by')) {
      findings.push({
        title: 'Divulgación de Tecnologías en Cabeceras HTTP',
        severity: 'Low',
        cwe: 'CWE-200'
      });
    }
    const riskyMethods = methodsAllowed.filter(m => ['PUT', 'DELETE', 'TRACE'].includes(m));
    if (riskyMethods.length > 0) {
      findings.push({
        title: `Métodos HTTP Peligrosos Habilitados (${riskyMethods.join(', ')})`,
        severity: 'Medium',
        cwe: 'CWE-650'
      });
    }
  }

  const sevCounts = { High: 0, Medium: 0, Low: 0 };
  findings.forEach(f => {
    if (sevCounts[f.severity] !== undefined) sevCounts[f.severity]++;
  });

  report = `🛡️ *Reporte Pericial — Auditoría Web OWASP*\n\n` +
           `• *Objetivo:* \`${targetUrl}\`\n` +
           `• *Perfil:* ${profText}\n` +
           `• *Tiempo de Ejecución:* \`${elapsedSec}s\`\n` +
           `• *Estado HTTP:* \`${httpCode > 0 ? httpCode : 'Sin respuesta'}\`\n\n` +
           `📊 *Matriz de Hallazgos (${findings.length} identificados):*\n` +
           `• 🔴 Críticos: *0*\n` +
           `• 🟠 Altos: *${sevCounts.High}*\n` +
           `• 🟡 Medios: *${sevCounts.Medium}*\n` +
           `• 🔵 Bajos: *${sevCounts.Low}*\n\n` +
           `📋 *Principales Hallazgos Evaluados:*\n`;

  findings.slice(0, 4).forEach((f, idx) => {
